/**
 * BacterI.A. - "Boss" reference bot, JavaScript port of config/Boss.py3, for testing
 * directly in the CodinGame IDE. Uses the CodinGame JS sandbox's global print()/
 * readline() (see config/reference_stub.js) - not Node's process.stdin/stdout.
 * Logic, phase order, and tuning constants are kept in lockstep with Boss.py3;
 * if you change one, change the other.
 *
 * Neighbor iteration deliberately avoids allocating an array/generator per call
 * (a single constant DX/DY offset table is walked with a plain for-loop instead) -
 * profiling under a CPU-quota-throttled container (mimicking a constrained judge
 * server) showed the array-allocating version could spike well past the 50ms
 * turn budget under GC/JIT pressure that the equivalent Python code never hit at
 * the same CPU limit. This reduces (but does not fully eliminate) that risk -
 * see memory notes on the Boss.js timeout investigation for the full story.
 */

const SPOT_VALUE = { 1: 20, 2: 60, 3: 140 };

const DX = [-1, -1, -1, 0, 0, 1, 1, 1];
const DY = [-1, 0, 1, -1, 1, -1, 0, 1];

// -----------------------------------------------------------------------
// Init
// -----------------------------------------------------------------------
const [MAP_SIZE, MY_ID] = readline().split(' ').map(Number);

// Cells are encoded as a single integer (x * MAP_SIZE + y) so Set/Map lookups don't
// need string keys - this also makes numeric sort on encoded opponent cells match
// Python's tuple-lexicographic sorted(opp_cells) (x first, then y).
const encode = (x, y) => x * MAP_SIZE + y;
const decode = (k) => [Math.floor(k / MAP_SIZE), k % MAP_SIZE];

const knownSpots = new Map(); // encoded key -> [type, energy]

const spotCount = parseInt(readline(), 10);
for (let i = 0; i < spotCount; i++) {
  const [sx, sy, stype] = readline().split(' ').map(Number);
  knownSpots.set(encode(sx, sy), [stype, SPOT_VALUE[stype] || 10]);
}

let turn = 0;

function countNeighbors(x, y, cellSet) {
  let count = 0;
  for (let i = 0; i < 8; i++) {
    const nx = x + DX[i];
    const ny = y + DY[i];
    if (nx >= 0 && nx < MAP_SIZE && ny >= 0 && ny < MAP_SIZE && cellSet.has(encode(nx, ny))) {
      count++;
    }
  }
  return count;
}

function hasNeighborIn(x, y, cellSet) {
  for (let i = 0; i < 8; i++) {
    const nx = x + DX[i];
    const ny = y + DY[i];
    if (nx >= 0 && nx < MAP_SIZE && ny >= 0 && ny < MAP_SIZE && cellSet.has(encode(nx, ny))) {
      return true;
    }
  }
  return false;
}

// BFS outward from the target over the fixed (never mutated) myCellsSet; the first
// frontier node touching it is adjacent to that owned cell and one step closer to
// the target - the single most efficient hop toward it this turn. Routes around
// opponent cells instead of searching through them: without this, if the shortest
// path to a target runs through enemy territory, this would keep returning that
// same blocked cell turn after turn (EXPAND onto an enemy cell is invalid, so the
// action is silently dropped), leaving the bot sitting on full energy with nothing
// to do instead of finding a way around.
function bfsNextStep(myCellsSet, oppCellsSet, targetX, targetY) {
  const targetKey = encode(targetX, targetY);
  if (myCellsSet.has(targetKey)) return null;
  const visited = new Set([targetKey]);
  const queue = [targetKey];
  let qi = 0;
  while (qi < queue.length) {
    const k = queue[qi++];
    const cx = Math.floor(k / MAP_SIZE);
    const cy = k % MAP_SIZE;
    for (let i = 0; i < 8; i++) {
      const nx = cx + DX[i];
      const ny = cy + DY[i];
      if (nx < 0 || nx >= MAP_SIZE || ny < 0 || ny >= MAP_SIZE) continue;
      const nk = nx * MAP_SIZE + ny;
      if (visited.has(nk)) continue;
      visited.add(nk);
      if (myCellsSet.has(nk)) return [cx, cy];
      if (oppCellsSet.has(nk)) continue;
      queue.push(nk);
    }
  }
  return null;
}

// An empty cell that is both adjacent to (cx, cy) and adjacent to our own territory
// (so it is a legal EXPAND target) - placing it raises our neighbor count around
// (cx, cy) by exactly one.
function findReinforcement(cx, cy, myCells, oppCells) {
  for (let i = 0; i < 8; i++) {
    const nx = cx + DX[i];
    const ny = cy + DY[i];
    if (nx < 0 || nx >= MAP_SIZE || ny < 0 || ny >= MAP_SIZE) continue;
    const nk = nx * MAP_SIZE + ny;
    if (myCells.has(nk) || oppCells.has(nk)) continue;
    if (hasNeighborIn(nx, ny, myCells)) return [nx, ny];
  }
  return null;
}

// Enemy cells adjacent to us where we are exactly one neighbor short of numerical
// superiority - reinforcing here turns a not-yet-legal ATTACK into a guaranteed one
// next turn, far cheaper than expanding blindly and hoping the numbers eventually
// favor us.
function attackSetupTargets(myCells, oppCells) {
  const targets = [];
  for (const ok of oppCells) {
    const ox = Math.floor(ok / MAP_SIZE);
    const oy = ok % MAP_SIZE;
    if (!hasNeighborIn(ox, oy, myCells)) continue;
    const myN = countNeighbors(ox, oy, myCells);
    const oppN = countNeighbors(ox, oy, oppCells);
    if (myN === oppN) {
      const r = findReinforcement(ox, oy, myCells, oppCells);
      if (r) targets.push(r);
    }
  }
  return targets;
}

// An empty cell adjacent to an opponent cell, picked closest to our own territory -
// the EXPAND fallback once local resources run out. An opponent's own cell is never
// a legal EXPAND destination, so aiming bfsNextStep directly at one degenerates the
// instant it's already adjacent (dist 1): the search returns that same occupied
// cell as the "step", which always fails the oppCells check and is silently
// dropped - the bot sits on full energy right at the front line instead of
// claiming the real empty ground still available around the fight. Scored against
// the colony's CENTROID rather than the exact minimum distance to every owned cell
// - the exact per-candidate scan cost double-digit milliseconds in Python once a
// colony reached the hundreds of cells (the real cause of a live per-turn timeout);
// kept the same centroid approach here for parity with Boss.py3.
function cellNearOpponent(myCells, oppCells) {
  if (myCells.size === 0) return null;
  let sumX = 0;
  let sumY = 0;
  for (const k of myCells) {
    sumX += Math.floor(k / MAP_SIZE);
    sumY += k % MAP_SIZE;
  }
  const avgX = sumX / myCells.size;
  const avgY = sumY / myCells.size;
  let best = null;
  let bestDist = null;
  for (const ok of oppCells) {
    const ox = Math.floor(ok / MAP_SIZE);
    const oy = ok % MAP_SIZE;
    for (let i = 0; i < 8; i++) {
      const nx = ox + DX[i];
      const ny = oy + DY[i];
      if (nx < 0 || nx >= MAP_SIZE || ny < 0 || ny >= MAP_SIZE) continue;
      const nk = nx * MAP_SIZE + ny;
      if (myCells.has(nk) || oppCells.has(nk)) continue;
      const d = Math.max(Math.abs(nx - avgX), Math.abs(ny - avgY));
      if (best === null || d < bestDist) {
        best = [nx, ny];
        bestDist = d;
      }
    }
  }
  return best;
}

// Our own cells on the front line where the opponent already has (or is tied for)
// enough neighbors to ATTACK and take them - reinforcing denies them an easy,
// guaranteed capture.
function vulnerableCellTargets(myCells, oppCells) {
  const targets = [];
  for (const mk of myCells) {
    const mx = Math.floor(mk / MAP_SIZE);
    const myY = mk % MAP_SIZE;
    if (!hasNeighborIn(mx, myY, oppCells)) continue;
    const myN = countNeighbors(mx, myY, myCells);
    const oppN = countNeighbors(mx, myY, oppCells);
    if (oppN >= myN) {
      const r = findReinforcement(mx, myY, myCells, oppCells);
      if (r) targets.push(r);
    }
  }
  return targets;
}

// -----------------------------------------------------------------------
// Game loop
// -----------------------------------------------------------------------
while (true) {
  turn++;
  const energyParts = readline().split(' ').map(Number);
  const myEnergy = energyParts[0];

  // --- Read my cells ---
  const myCellCount = parseInt(readline(), 10);
  const myCells = new Set();
  for (let i = 0; i < myCellCount; i++) {
    const [x, y] = readline().split(' ').map(Number);
    myCells.add(encode(x, y));
  }

  // --- Read opponent cells ---
  const oppCellCount = parseInt(readline(), 10);
  const oppCells = new Set();
  for (let i = 0; i < oppCellCount; i++) {
    const [x, y] = readline().split(' ').map(Number);
    oppCells.add(encode(x, y));
  }

  // --- Read visible spots ---
  const visSpotCount = parseInt(readline(), 10);
  for (let i = 0; i < visSpotCount; i++) {
    const [sx, sy, stype, rem] = readline().split(' ').map(Number);
    knownSpots.set(encode(sx, sy), [stype, rem]);
  }

  let actions;
  try {
    actions = decideActions(myEnergy, myCells, oppCells);
  } catch (err) {
    // Never let a bug in the strategy leave us with no output at all - a crash here
    // would look identical to a timeout to the referee (no line ever printed), which
    // is strictly worse than a wasted WAIT this one turn.
    actions = ['WAIT'];
  }

  print(actions.join('; '));
}

function decideActions(myEnergyIn, myCells, oppCells) {
  let myEnergy = myEnergyIn;
  const actions = [];

  // --- Phase: Attack adjacent enemies with numerical superiority ---
  if (oppCells.size > 0 && myEnergy >= 2) {
    const sortedOpp = [...oppCells].sort((a, b) => a - b);
    for (const ok of sortedOpp) {
      if (actions.length >= 5 || myEnergy < 2) break;
      const ox = Math.floor(ok / MAP_SIZE);
      const oy = ok % MAP_SIZE;
      const myN = countNeighbors(ox, oy, myCells);
      const oppN = countNeighbors(ox, oy, oppCells);
      const adjToMine = hasNeighborIn(ox, oy, myCells);
      if (adjToMine && myN > oppN) {
        actions.push(`ATTACK ${ox} ${oy}`);
        myEnergy -= 2;
        // Do not assume capture or reward; referee state arrives next turn.
      }
    }
  }

  // --- Phase: Tactical reinforcement ---
  // A true full-depth search over "up to 5 actions across thousands of candidate
  // cells" is not viable inside the 50ms per-turn budget, so this is a cheap,
  // targeted heuristic instead of a game-tree search: look only at cells already
  // in contact (adjacent) with the enemy, where a single reinforcement either (a)
  // tips a near-miss ATTACK into a guaranteed one next turn, or (b) saves one of
  // our own front-line cells that the opponent could otherwise capture for free.
  // Budget of 3 (not 2) reflects that a successful ATTACK is worth a flat scoring
  // bonus on top of its own per-turn territory value.
  const placed = new Set();

  if (oppCells.size > 0 && actions.length < 5 && myEnergy >= 2) {
    const tacticalBudget = Math.min(3, 5 - actions.length);
    let tacticalUsed = 0;
    const tacticalTargets = attackSetupTargets(myCells, oppCells).concat(vulnerableCellTargets(myCells, oppCells));
    for (const target of tacticalTargets) {
      if (tacticalUsed >= tacticalBudget || myEnergy < 2) break;
      const tk = encode(target[0], target[1]);
      if (myCells.has(tk) || oppCells.has(tk) || placed.has(tk)) continue; // already reinforced this turn
      actions.push(`EXPAND ${target[0]} ${target[1]}`);
      myEnergy -= 2;
      tacticalUsed++;
      placed.add(tk);
    }
  }

  // --- Phase: Expand ---
  const undepleted = new Map();
  for (const [k, info] of knownSpots) {
    if (info[1] > 0) undepleted.set(k, info);
  }

  const rawDistance = (pos) => {
    let min = Infinity;
    for (const ck of myCells) {
      const cx = Math.floor(ck / MAP_SIZE);
      const cy = ck % MAP_SIZE;
      const d = Math.max(Math.abs(pos[0] - cx), Math.abs(pos[1] - cy));
      if (d < min) min = d;
    }
    return min;
  };

  // Oppression-aware priority (lower is better) - a pure "nearest empty ground"
  // scan treats every target as equally worth reaching, which wins territory but
  // not fights or resource denial. A bigger spot is worth travelling a bit further
  // for, and a target nearer the OPPONENT than to us is worth extra priority -
  // claiming it both grows our colony and starves theirs.
  const targetPriority = (pos) => {
    const dist = rawDistance(pos);
    const info = knownSpots.get(encode(pos[0], pos[1]));
    const valueBonus = info ? Math.floor((SPOT_VALUE[info[0]] || 0) / 10) : 0;
    let oppressionBonus = 0;
    if (oppCells.size > 0) {
      let oppDist = Infinity;
      for (const ok of oppCells) {
        const ox = Math.floor(ok / MAP_SIZE);
        const oy = ok % MAP_SIZE;
        const d = Math.max(Math.abs(pos[0] - ox), Math.abs(pos[1] - oy));
        if (d < oppDist) oppDist = d;
      }
      if (oppDist < dist) oppressionBonus = 3;
    }
    return dist - valueBonus - oppressionBonus;
  };

  // Where to head once there's nothing left to secure: the opponent's corner is
  // always known exactly (start positions are fixed).
  const oppCorner = MY_ID === 0 ? [MAP_SIZE - 1, MAP_SIZE - 1] : [0, 0];

  const undepletedSorted = [...undepleted.keys()].map(decode);
  undepletedSorted.sort((a, b) => targetPriority(a) - targetPriority(b));
  const oppTarget = (oppCells.size > 0 ? cellNearOpponent(myCells, oppCells) : null) || oppCorner;

  // The opponent-contact target competes on equal footing with every known spot for
  // BOTH the guaranteed baseline hop and the bonus actions below - not just as a
  // fallback once spots run dry - so a strong oppression opportunity can win the
  // baseline slot over one more (weaker) spot.
  const allTargets = undepletedSorted.concat([oppTarget]);
  allTargets.sort((a, b) => targetPriority(a) - targetPriority(b));
  const nearest = allTargets[0];
  const distToNearest = rawDistance(nearest);

  // Always guarantee at least one directed hop per turn - whether still traveling
  // to the nearest spot or already parked on one.
  const safetyMargin = 6;
  const reserveNeeded = distToNearest * 2 + safetyMargin;
  const surplus = Math.max(0, myEnergy - reserveNeeded);
  const bonusActions = Math.min(4, Math.floor(surplus / 2));
  const expandBudget = Math.min(5 - actions.length, 1 + bonusActions);
  let expandUsed = 0;

  // Guaranteed critical-path hop toward the nearest target (skip if already there).
  if (expandUsed < expandBudget && myEnergy >= 2 && distToNearest > 0) {
    const step = bfsNextStep(myCells, oppCells, nearest[0], nearest[1]);
    if (step) {
      const sk = encode(step[0], step[1]);
      if (!myCells.has(sk) && !oppCells.has(sk) && !placed.has(sk)) {
        actions.push(`EXPAND ${step[0]} ${step[1]}`);
        myEnergy -= 2;
        expandUsed++;
        placed.add(sk);
      }
    }
  }

  // Any remaining budget goes toward the next-closest known targets, one directed
  // hop each - deduplicated against `placed` since distinct targets often share the
  // same first hop while the frontier is still a single point, and only the first
  // copy of a same-turn EXPAND can ever succeed (no chaining).
  if (expandUsed < expandBudget && myEnergy >= 2) {
    for (const target of allTargets) {
      if (expandUsed >= expandBudget || myEnergy < 2) break;
      const step = bfsNextStep(myCells, oppCells, target[0], target[1]);
      if (step) {
        const sk = encode(step[0], step[1]);
        if (!myCells.has(sk) && !oppCells.has(sk) && !placed.has(sk)) {
          actions.push(`EXPAND ${step[0]} ${step[1]}`);
          myEnergy -= 2;
          expandUsed++;
          placed.add(sk);
        }
      }
    }
  }

  // --- Phase: Emergency fuel - every real action costs 2, so a colony that drops
  // below that with no reachable income has no way back in on its own. Sacrificing
  // whichever owned cell is FARTHEST from the target we're currently pursuing
  // sidesteps colony shape (blob vs. thin BFS-grown line) entirely - it always
  // finds a candidate, and a distant cell can't be part of the active frontier or
  // the path we're relying on right now, so it can't undo the progress that was
  // just made.
  if (myEnergy < 2 && actions.length < 5 && myCells.size > 15) {
    const [tx, ty] = nearest;
    let sacrifice = null;
    let sacrificeDist = -1;
    for (const ck of myCells) {
      const info = knownSpots.get(ck);
      if (info && info[1] > 0) continue;
      const cx = Math.floor(ck / MAP_SIZE);
      const cy = ck % MAP_SIZE;
      const d = Math.max(Math.abs(cx - tx), Math.abs(cy - ty));
      if (d > sacrificeDist) {
        sacrificeDist = d;
        sacrifice = [cx, cy];
      }
    }
    if (sacrifice) {
      actions.push(`APOPTOSIS ${sacrifice[0]} ${sacrifice[1]}`);
      myCells.delete(encode(sacrifice[0], sacrifice[1]));
      myEnergy += 1;
    }
  }

  if (actions.length === 0) actions.push('WAIT');

  return actions;
}
